const nativeChapterModules = Object.freeze({"chapter-01":[{"id":"patterns","title":"找规律","practices":[{"id":"patterns-1","title":"闯关 1","difficulty":"基础","prompt":"4，7，10，13，( )","answer":"16","explanation":"每次增加 3。"},{"id":"patterns-2","title":"闯关 2","difficulty":"基础","prompt":"1，4，9，16，( )","answer":"25","explanation":"这是平方数列，依次是 1²、2²、3²、4²、5²。"},{"id":"patterns-3","title":"闯关 3","difficulty":"进阶","prompt":"3，6，12，24，( )","answer":"48","explanation":"每次扩大到原来的 2 倍。"},{"id":"patterns-4","title":"闯关 4","difficulty":"进阶","prompt":"5，8，11，14，17，( )","answer":"20","explanation":"这是等差数列，每次加 3。"},{"id":"patterns-5","title":"闯关 5","difficulty":"提高","prompt":"2，4，8，16，( )","answer":"32","explanation":"每次都是前一个数的 2 倍。"},{"id":"patterns-6","title":"闯关 6","difficulty":"挑战","prompt":"1，2，4，7，11，( )","answer":"16","explanation":"相邻两项依次加 1、2、3、4，下一次加 5，所以是 16。"},{"id":"patterns-8","title":"闯关 8","difficulty":"提高","prompt":"2，5，10，17，( )","answer":"26","explanation":"相邻两项分别加 3、5、7，下一次加 9，所以是 26。"},{"id":"patterns-9","title":"闯关 9","difficulty":"提高","prompt":"8，7，10，9，12，11，( )","answer":"14","explanation":"奇数位是 8、10、12，依次加 2，所以下一项是 14。"},{"id":"patterns-11","title":"闯关 11","difficulty":"提高","prompt":"3，5，9，15，( )","answer":"23","explanation":"相邻两项依次加 2、4、6，下一次加 8，所以是 23。"},{"id":"patterns-12","title":"闯关 12","difficulty":"挑战","prompt":"2，6，12，20，30，( )","answer":"42","explanation":"相邻两项依次加 4、6、8、10，下一次加 12，所以是 42。"},{"id":"patterns-13","title":"闯关 13","difficulty":"挑战","prompt":"10，8，11，9，12，10，( )","answer":"13","explanation":"奇数位是 10、11、12，依次加 1，所以下一项是 13。"},{"id":"patterns-14","title":"闯关 14","difficulty":"提高","prompt":"7，10，14，19，25，( )","answer":"32","explanation":"相邻两项依次加 3、4、5、6，下一次加 7，所以是 32。"},{"id":"patterns-15","title":"闯关 15","difficulty":"挑战","prompt":"2，3，5，8，12，( )","answer":"17","explanation":"相邻两项依次加 1、2、3、4，下一次加 5，所以是 17。"}]},{"id":"quick-calculation","title":"巧算与凑整","practices":[{"id":"quick-calculation-1","title":"凑成整百","difficulty":"基础","prompt":"计算 297 + 36 + 3。","answer":"336","explanation":"297 + 3 = 300，再加 36，得到 336。"},{"id":"quick-calculation-2","title":"接近整百","difficulty":"基础","prompt":"计算 456 + 99。","answer":"555","explanation":"99 = 100 - 1，所以 456 + 99 = 456 + 100 - 1 = 555。"},{"id":"quick-calculation-3","title":"加减凑整","difficulty":"进阶","prompt":"计算 1000 - 398 - 2。","answer":"600","explanation":"398 + 2 = 400，所以 1000 - 398 - 2 = 1000 - 400 = 600。"},{"id":"quick-calculation-4","title":"乘法拆分","difficulty":"进阶","prompt":"计算 25 × 16。","answer":"400","explanation":"16 = 4 × 4，25 × 4 = 100，再乘 4 得 400。"},{"id":"quick-calculation-5","title":"首尾配对","difficulty":"提高","prompt":"计算 21 + 22 + 23 + 24 + 25 + 26 + 27 + 28 + 29。","answer":"225","explanation":"首尾配对都是 50：21+29、22+28、23+27、24+26 共 4 对，再加 25，得 225。"},{"id":"quick-calculation-6","title":"综合凑整","difficulty":"挑战","prompt":"计算 998 + 397 + 2 + 3。","answer":"1400","explanation":"998 + 2 = 1000，397 + 3 = 400，所以总和是 1400。"}]},{"id":"arithmetic-series","title":"等差数列与配对求和","practices":[{"id":"arithmetic-series-1","title":"下一项","difficulty":"基础","prompt":"数列 4，9，14，19，下一项是多少？","answer":"24","explanation":"相邻两项都相差 5，所以 19 + 5 = 24。"},{"id":"arithmetic-series-2","title":"第 8 项","difficulty":"基础","prompt":"数列 2，6，10，14……第 8 项是多少？","answer":"30","explanation":"第 8 项比第 1 项多 7 个公差 4，所以 2 + 7 × 4 = 30。"},{"id":"arithmetic-series-3","title":"求项数","difficulty":"进阶","prompt":"数列 6，10，14，18，……，46 一共有多少项？","answer":"11","explanation":"46 - 6 = 40，40 ÷ 4 = 10 个间隔，所以有 11 项。"},{"id":"arithmetic-series-4","title":"从 1 加到 30","difficulty":"进阶","prompt":"1 + 2 + 3 + …… + 30 的和是多少？","answer":"465","explanation":"1+30=31，共 15 对，所以总和是 31 × 15 = 465。"},{"id":"arithmetic-series-5","title":"奇数求和","difficulty":"提高","prompt":"1 + 3 + 5 + 7 + 9 + 11 + 13 + 15 的和是多少？","answer":"64","explanation":"首尾和 16，共 4 对，所以总和 16 × 4 = 64。"},{"id":"arithmetic-series-6","title":"综合求和","difficulty":"挑战","prompt":"数列 7，12，17，22，……，52 的所有项之和是多少？","answer":"295","explanation":"公差 5，52-7=45，有 9 个间隔、10 项；首尾和 59，共 5 对，所以和是 295。"}]},{"id":"periodicity","title":"周期问题","practices":[{"id":"periodicity-1","title":"颜色循环","difficulty":"基础","prompt":"按“红、黄、蓝、红、黄、蓝……”排列，第 20 个是什么颜色？","answer":"黄","explanation":"3 个一组，20 ÷ 3 = 6 余 2，第 20 个是每组第 2 个：黄。"},{"id":"periodicity-2","title":"图形周期","difficulty":"基础","prompt":"按“○、□、△、○、□、△……”排列，第 17 个图形是什么？","answer":"□","explanation":"3 个一组，17 ÷ 3 = 5 余 2，第 17 个是每组第 2 个 □。"},{"id":"periodicity-3","title":"星期推算","difficulty":"进阶","prompt":"今天是星期五，10 天后是星期几？","answer":"星期一","explanation":"10 ÷ 7 = 1 余 3，从星期五往后数 3 天是星期一。"},{"id":"periodicity-4","title":"余 0 情况","difficulty":"进阶","prompt":"按“甲、乙、丙、丁”循环排列，第 32 个是谁？","answer":"丁","explanation":"4 个一组，32 ÷ 4 = 8 余 0，余 0 表示每组最后一个，所以是丁。"},{"id":"periodicity-5","title":"数字周期","difficulty":"提高","prompt":"数列 2，5，8，2，5，8……第 41 项是多少？","answer":"5","explanation":"3 项一组，41 ÷ 3 = 13 余 2，第 41 项是每组第 2 项 5。"},{"id":"periodicity-6","title":"复杂周期","difficulty":"挑战","prompt":"按“1，1，2，3，1，1，2，3……”排列，第 50 个数是多少？","answer":"1","explanation":"4 个一组，50 ÷ 4 = 12 余 2，第 50 个是每组第 2 个 1。"}]},{"id":"enumeration","title":"有序枚举","practices":[{"id":"enumeration-1","title":"两位数","difficulty":"基础","prompt":"用 4、5、6 可以组成多少个没有重复数字的两位数？","answer":"6","explanation":"十位有 3 种选法，个位剩 2 种，所以 3 × 2 = 6 个。"},{"id":"enumeration-2","title":"三种搭配","difficulty":"基础","prompt":"有 2 顶帽子和 4 件上衣，每次选一顶帽子和一件上衣，一共有多少种搭配？","answer":"8","explanation":"每顶帽子可搭配 4 件上衣，2 顶帽子共 2 × 4 = 8 种。"},{"id":"enumeration-3","title":"分类计数","difficulty":"进阶","prompt":"从 A、B、C、D 四人中选 1 人当组长，有多少种选法？","answer":"4","explanation":"组长只选 1 人，可以是 A、B、C、D，共 4 种。"},{"id":"enumeration-4","title":"选两人握手","difficulty":"提高","prompt":"4 个人两两握手，每两人握一次，一共握手多少次？","answer":"6","explanation":"A 可和 3 人握，B 再和 2 人握，C 再和 1 人握，共 3 + 2 + 1 = 6 次。"},{"id":"enumeration-5","title":"有序安排","difficulty":"提高","prompt":"甲、乙、丙三人排成一排，一共有多少种不同排法？","answer":"6","explanation":"第 1 个位置 3 种，第 2 个位置 2 种，第 3 个位置 1 种，共 3 × 2 × 1 = 6 种。"},{"id":"enumeration-6","title":"不重不漏","difficulty":"挑战","prompt":"用 0、1、2、3 可以组成多少个没有重复数字的两位数？","answer":"9","explanation":"十位不能是 0，有 1、2、3 共 3 种；个位可从剩下 3 个数字中选，共 3 × 3 = 9 个。"}]},{"id":"add-multiply-principle","title":"加法原理与乘法原理","practices":[{"id":"add-multiply-principle-1","title":"只选一种","difficulty":"基础","prompt":"盒子里有 5 支铅笔和 3 支钢笔，只选 1 支笔，一共有多少种选法？","answer":"8","explanation":"选铅笔或钢笔是分类选择，5 + 3 = 8 种。"},{"id":"add-multiply-principle-2","title":"一套搭配","difficulty":"基础","prompt":"有 4 件上衣和 2 条裤子，每次选 1 件上衣和 1 条裤子，一共有多少种搭配？","answer":"8","explanation":"先选上衣 4 种，再选裤子 2 种，共 4 × 2 = 8 种。"},{"id":"add-multiply-principle-3","title":"路线选择","difficulty":"进阶","prompt":"从家到学校必须经过公园。家到公园有 3 条路，公园到学校有 2 条路，一共有多少种走法？","answer":"6","explanation":"先走家到公园，再走公园到学校，是分步选择，3 × 2 = 6。"},{"id":"add-multiply-principle-4","title":"两种方案","difficulty":"进阶","prompt":"小明去图书馆，可以坐 2 路公交，也可以坐 5 路公交；2 路有 3 个班次，5 路有 4 个班次。共有多少种乘车选择？","answer":"7","explanation":"坐 2 路或 5 路是分类选择，所以 3 + 4 = 7 种。"},{"id":"add-multiply-principle-5","title":"混合计数","difficulty":"提高","prompt":"早餐可以选中式或西式。中式有 2 种主食和 3 种饮品；西式有 3 种套餐。共有多少种早餐选择？","answer":"9","explanation":"中式是分步：2×3=6 种；西式是 3 种；分类相加 6+3=9。"},{"id":"add-multiply-principle-6","title":"密码组合","difficulty":"挑战","prompt":"一个两位密码，十位可选 1、2、3，个位可选 0、5、8、9，一共有多少种密码？","answer":"12","explanation":"十位和个位都要选，是分步计数，3 × 4 = 12。"}]},{"id":"inclusion-exclusion","title":"容斥初步","practices":[{"id":"inclusion-exclusion-1","title":"求并集","difficulty":"基础","prompt":"有 12 人喜欢画画，10 人喜欢唱歌，其中 4 人两项都喜欢。至少喜欢一项的有多少人？","answer":"18","explanation":"12 + 10 - 4 = 18，因为两项都喜欢的人被重复算了一次。"},{"id":"inclusion-exclusion-2","title":"反求重叠","difficulty":"进阶","prompt":"喜欢数学的有 16 人，喜欢科学的有 14 人，至少喜欢一项的有 24 人，两项都喜欢的有多少人？","answer":"6","explanation":"16 + 14 = 30，比 24 多 6，多出来的是重复计算的重叠部分。"},{"id":"inclusion-exclusion-3","title":"都不参加","difficulty":"进阶","prompt":"全班 35 人，参加足球的有 18 人，参加篮球的有 15 人，两项都参加的有 5 人。两项都不参加的有多少人？","answer":"7","explanation":"至少参加一项的有 18 + 15 - 5 = 28 人，都不参加的是 35 - 28 = 7 人。"},{"id":"inclusion-exclusion-4","title":"调查统计","difficulty":"提高","prompt":"有 25 人订语文报，22 人订数学报，10 人两种都订，至少订一种报纸的有多少人？","answer":"37","explanation":"25 + 22 - 10 = 37。"},{"id":"inclusion-exclusion-5","title":"至少一项","difficulty":"提高","prompt":"有 20 人会游泳，18 人会滑冰，8 人两项都会。至少会一项的有多少人？","answer":"30","explanation":"20 + 18 - 8 = 30。"},{"id":"inclusion-exclusion-6","title":"只会一项","difficulty":"挑战","prompt":"会弹琴的有 15 人，会画画的有 13 人，两项都会的有 4 人。只会其中一项的有多少人？","answer":"20","explanation":"只会弹琴 15 - 4 = 11，只会画画 13 - 4 = 9，共 20 人。"}]},{"id":"sum-diff","title":"和差倍问题","practices":[{"id":"sum-diff-1","title":"闯关 1","difficulty":"基础","prompt":"两个数的和是 16，差是 2，较大的数是多少？","answer":"9","explanation":"(16 + 2) ÷ 2 = 9。"},{"id":"sum-diff-2","title":"闯关 2","difficulty":"基础","prompt":"一个数是另一个数的 3 倍，小数是 5，大数是多少？","answer":"15","explanation":"5 × 3 = 15。"},{"id":"sum-diff-3","title":"闯关 3","difficulty":"进阶","prompt":"甲乙两数和为 30，甲比乙多 6，乙是多少？","answer":"12","explanation":"较小数 = (30 - 6) ÷ 2 = 12。"},{"id":"sum-diff-4","title":"闯关 4","difficulty":"进阶","prompt":"两个数的和是 28，大数比小数多 8，小数是多少？","answer":"10","explanation":"(28 - 8) ÷ 2 = 10。"},{"id":"sum-diff-5","title":"闯关 5","difficulty":"提高","prompt":"甲是乙的 2 倍，甲乙一共 18，乙是多少？","answer":"6","explanation":"一共 3 份，18 ÷ 3 = 6。"},{"id":"sum-diff-6","title":"闯关 6","difficulty":"挑战","prompt":"大数是小数的 5 倍，它们相差 16，小数是多少？","answer":"4","explanation":"相差 4 份，16 ÷ 4 = 4。"},{"id":"sum-diff-8","title":"闯关 8","difficulty":"提高","prompt":"甲乙两数的和是 21，甲是乙的 2 倍，乙是多少？","answer":"7","explanation":"一共 3 份，21 ÷ 3 = 7。"},{"id":"sum-diff-9","title":"闯关 9","difficulty":"提高","prompt":"大数比小数多 12，两数和是 36，小数是多少？","answer":"12","explanation":"较小数 = (36 - 12) ÷ 2 = 12。"},{"id":"sum-diff-11","title":"闯关 11","difficulty":"提高","prompt":"甲乙两数的和是 32，甲比乙多 4，甲是多少？","answer":"18","explanation":"较大数 = (32 + 4) ÷ 2 = 18。"},{"id":"sum-diff-12","title":"闯关 12","difficulty":"挑战","prompt":"大数是小数的 4 倍，两数和是 25，小数是多少？","answer":"5","explanation":"一共 5 份，25 ÷ 5 = 5。"},{"id":"sum-diff-13","title":"闯关 13","difficulty":"提高","prompt":"甲是乙的 3 倍，乙是 6，甲乙和是多少？","answer":"24","explanation":"甲是 18，18 + 6 = 24。"},{"id":"sum-diff-14","title":"闯关 14","difficulty":"挑战","prompt":"大数比小数多 18，且大数是小数的 4 倍，小数是多少？","answer":"6","explanation":"相差 3 份，18 ÷ 3 = 6。"},{"id":"sum-diff-15","title":"闯关 15","difficulty":"提高","prompt":"两个数的和是 40，差是 10，较小的数是多少？","answer":"15","explanation":"较小数 = (40 - 10) ÷ 2 = 15。"}]},{"id":"unit-rate","title":"归一归总问题","practices":[{"id":"unit-rate-1","title":"单价归一","difficulty":"基础","prompt":"4 支铅笔 12 元，买 7 支铅笔多少元？","answer":"21","explanation":"1 支铅笔 12 ÷ 4 = 3 元，7 支是 3 × 7 = 21 元。"},{"id":"unit-rate-2","title":"速度归一","difficulty":"基础","prompt":"小明 5 分钟走 300 米，照这样走，8 分钟走多少米？","answer":"480","explanation":"每分钟走 300 ÷ 5 = 60 米，8 分钟走 60 × 8 = 480 米。"},{"id":"unit-rate-3","title":"多人多天","difficulty":"进阶","prompt":"3 人 4 天吃 36 个苹果，平均 1 人 1 天吃几个苹果？","answer":"3","explanation":"3 人 4 天共有 12 人天，36 ÷ 12 = 3 个。"},{"id":"unit-rate-4","title":"机器效率","difficulty":"提高","prompt":"5 台机器 6 小时生产 240 个零件，1 台机器 1 小时生产多少个？","answer":"8","explanation":"总机器小时是 5 × 6 = 30，240 ÷ 30 = 8 个。"},{"id":"unit-rate-5","title":"归一再放大","difficulty":"提高","prompt":"6 个工人 3 天修路 90 米，照这样，4 个工人 5 天修路多少米？","answer":"100","explanation":"1 个工人 1 天修 90 ÷ 6 ÷ 3 = 5 米，4 个工人 5 天修 5 × 4 × 5 = 100 米。"},{"id":"unit-rate-6","title":"反求数量","difficulty":"挑战","prompt":"3 台机器 4 小时生产 96 个零件，照这样，2 台机器生产 64 个零件需要几小时？","answer":"4","explanation":"1 台机器 1 小时生产 96 ÷ 3 ÷ 4 = 8 个；2 台机器每小时生产 16 个，64 ÷ 16 = 4 小时。"}]},{"id":"surplus-deficit","title":"盈亏问题","practices":[{"id":"surplus-deficit-1","title":"一盈一亏","difficulty":"基础","prompt":"分糖果，每人 5 颗多 12 颗，每人 6 颗少 3 颗。有几个小朋友？","answer":"15","explanation":"每人多分 1 颗，总差是 12 + 3 = 15 颗，所以有 15 个小朋友。"},{"id":"surplus-deficit-2","title":"求人数","difficulty":"基础","prompt":"分铅笔，每人 4 支多 8 支，每人 5 支刚好分完。有几个人？","answer":"8","explanation":"每人多分 1 支，原来多出的 8 支刚好补上，所以有 8 人。"},{"id":"surplus-deficit-3","title":"两次都盈","difficulty":"进阶","prompt":"分练习本，每人 3 本多 15 本，每人 6 本多 3 本。有几个学生？","answer":"4","explanation":"每人多分 3 本，剩余减少 12 本，人数是 12 ÷ 3 = 4。"},{"id":"surplus-deficit-4","title":"两次都亏","difficulty":"提高","prompt":"分书，每人 7 本少 10 本，每人 5 本少 2 本。有几个学生？","answer":"4","explanation":"每人少分 2 本，缺少量从 10 本减少到 2 本，差 8 本，8 ÷ 2 = 4 人。"},{"id":"surplus-deficit-5","title":"求总量","difficulty":"提高","prompt":"分苹果，每人 4 个多 6 个，每人 6 个少 4 个。一共有多少个苹果？","answer":"26","explanation":"人数是 (6 + 4) ÷ (6 - 4) = 5 人，总数是 4 × 5 + 6 = 26 个。"},{"id":"surplus-deficit-6","title":"方案比较","difficulty":"挑战","prompt":"分卡片，每人 8 张少 12 张，每人 5 张多 9 张。共有多少张卡片？","answer":"44","explanation":"人数是 (12 + 9) ÷ (8 - 5) = 7 人，总数是 5 × 7 + 9 = 44 张。"}]},{"id":"chicken-rabbit","title":"鸡兔同笼","practices":[{"id":"chicken-rabbit-1","title":"闯关 1","difficulty":"基础","prompt":"鸡兔共有 4 只，脚有 12 只，兔有几只？","answer":"2","explanation":"全鸡应有 8 只脚，多 4 只脚，所以有 2 只兔。"},{"id":"chicken-rabbit-2","title":"闯关 2","difficulty":"基础","prompt":"鸡兔共有 5 只，脚有 14 只，鸡有几只？","answer":"3","explanation":"全鸡有 10 只脚，多 4 只脚，所以兔有 2 只，鸡有 3 只。"},{"id":"chicken-rabbit-3","title":"闯关 3","difficulty":"进阶","prompt":"鸡兔共有 7 只，脚有 20 只，兔有几只？","answer":"3","explanation":"全鸡有 14 只脚，多 6 只脚，所以兔有 3 只。"},{"id":"chicken-rabbit-4","title":"闯关 4","difficulty":"进阶","prompt":"鸡兔共有 8 只，脚有 24 只，鸡有几只？","answer":"4","explanation":"全鸡有 16 只脚，多 8 只脚，所以兔有 4 只，鸡也有 4 只。"},{"id":"chicken-rabbit-5","title":"闯关 5","difficulty":"提高","prompt":"鸡兔共有 9 只，脚有 26 只，兔有几只？","answer":"4","explanation":"全鸡有 18 只脚，多 8 只脚，所以兔有 4 只。"},{"id":"chicken-rabbit-6","title":"闯关 6","difficulty":"提高","prompt":"鸡兔共有 10 只，脚有 32 只，鸡有几只？","answer":"4","explanation":"全鸡有 20 只脚，多 12 只脚，所以兔有 6 只，鸡有 4 只。"},{"id":"chicken-rabbit-7","title":"闯关 7","difficulty":"挑战","prompt":"鸡兔共有 12 只，脚有 34 只，兔有几只？","answer":"5","explanation":"全鸡有 24 只脚，多 10 只脚，所以兔有 5 只。"},{"id":"chicken-rabbit-8","title":"闯关 8","difficulty":"挑战","prompt":"鸡兔共有 11 只，脚有 30 只，鸡有几只？","answer":"7","explanation":"全鸡有 22 只脚，多 8 只脚，所以兔有 4 只，鸡有 7 只。"},{"id":"chicken-rabbit-9","title":"闯关 9","difficulty":"提高","prompt":"鸡兔共有 13 只，脚有 38 只，兔有几只？","answer":"6","explanation":"全鸡有 26 只脚，多 12 只脚，所以兔有 6 只。"},{"id":"chicken-rabbit-10","title":"闯关 10","difficulty":"挑战","prompt":"鸡兔共有 15 只，脚有 44 只，鸡有几只？","answer":"8","explanation":"全鸡有 30 只脚，多 14 只脚，所以兔有 7 只，鸡有 8 只。"}]},{"id":"average","title":"平均数问题","practices":[{"id":"average-1","title":"求平均","difficulty":"基础","prompt":"三个数分别是 12、18、24，它们的平均数是多少？","answer":"18","explanation":"平均数 = (12 + 18 + 24) ÷ 3 = 18。"},{"id":"average-2","title":"求总数","difficulty":"基础","prompt":"5 个数的平均数是 16，这 5 个数的和是多少？","answer":"80","explanation":"总数 = 平均数 × 个数，16 × 5 = 80。"},{"id":"average-3","title":"补一个数","difficulty":"进阶","prompt":"前 3 次平均分是 82 分，第 4 次考多少分，4 次平均分才能达到 85 分？","answer":"94","explanation":"目标总分 85 × 4 = 340，前 3 次总分 82 × 3 = 246，第 4 次要 340 - 246 = 94 分。"},{"id":"average-4","title":"去掉一个数","difficulty":"提高","prompt":"5 个数的平均数是 20，去掉一个数后，剩下 4 个数平均数是 18。去掉的数是多少？","answer":"28","explanation":"原总和 20 × 5 = 100，剩下总和 18 × 4 = 72，去掉的是 100 - 72 = 28。"},{"id":"average-5","title":"调平均数","difficulty":"提高","prompt":"4 个数的平均数是 15，如果其中一个数增加 8，新的平均数是多少？","answer":"17","explanation":"总和增加 8，平均数增加 8 ÷ 4 = 2，所以新平均数是 17。"},{"id":"average-6","title":"平均速度","difficulty":"挑战","prompt":"小明前 2 天平均每天读 18 页，后 3 天平均每天读 22 页，5 天平均每天读多少页？","answer":"20.4","explanation":"总页数是 18 × 2 + 22 × 3 = 102 页，5 天平均 102 ÷ 5 = 20.4 页。"}]}],"chapter-02":[{"id":"pigeonhole-principle","title":"抽屉原理","practices":[{"id":"pigeonhole-principle-1","title":"同色球","difficulty":"基础","prompt":"袋中有红球、黄球、蓝球各若干个。至少取出多少个球，才能保证有 2 个颜色相同？","answer":"4","explanation":"最坏先取出红、黄、蓝各 1 个，第 4 个一定和其中一种颜色相同。"},{"id":"pigeonhole-principle-2","title":"生日月份","difficulty":"基础","prompt":"班里有 25 人，至少有几个人出生在同一个月份？","answer":"3","explanation":"12 个月每月最多先放 2 人可放 24 人，第 25 人会让某个月达到 3 人。"},{"id":"pigeonhole-principle-3","title":"同余数","difficulty":"进阶","prompt":"任意取 8 个整数，至少有几个数除以 3 的余数相同？","answer":"3","explanation":"除以 3 只有 0、1、2 三种余数。8 个数平均放进 3 类，至少一类有 3 个。"},{"id":"pigeonhole-principle-4","title":"保证有 3 个","difficulty":"进阶","prompt":"有黑、白两种棋子。至少取多少枚，才能保证有 3 枚颜色相同？","answer":"5","explanation":"最坏先取黑 2 枚、白 2 枚，第 5 枚一定让某种颜色达到 3 枚。"},{"id":"pigeonhole-principle-5","title":"分组保证","difficulty":"提高","prompt":"把 31 本书放进 5 个书架，至少有一个书架上有多少本书？","answer":"7","explanation":"若每个书架最多 6 本，共能放 30 本；第 31 本会让某个书架达到 7 本。"},{"id":"pigeonhole-principle-6","title":"综合保证","difficulty":"挑战","prompt":"从 1 到 20 中任取 11 个数，为什么一定有两个数的和是 21？","answer":"因为可分成 10 对","explanation":"把数字分成 (1,20)、(2,19)、……、(10,11) 共 10 个抽屉，取 11 个数，必有一对都被取到。"}]},{"id":"counting-transfer","title":"计数换乘站","practices":[{"id":"counting-transfer-1","title":"限制位置","difficulty":"基础","prompt":"用 1、2、3 可以组成多少个没有重复数字的两位数？","answer":"6","explanation":"十位 3 种，个位剩 2 种，共 3×2=6。"},{"id":"counting-transfer-2","title":"分类路线","difficulty":"基础","prompt":"从 A 到 C，可以直达有 2 条路；也可以经 B，A 到 B 有 2 条路，B 到 C 有 3 条路。共有多少种走法？","answer":"8","explanation":"直达 2 种，经 B 有 2×3=6 种，共 8 种。"},{"id":"counting-transfer-3","title":"至少一项","difficulty":"进阶","prompt":"参加数学社的有 15 人，参加科学社的有 12 人，两社都参加的有 4 人。至少参加一个社团的有多少人？","answer":"23","explanation":"15+12-4=23。"},{"id":"counting-transfer-4","title":"不符合条件","difficulty":"进阶","prompt":"用 0、1、2、3 组成没有重复数字的两位数，一共有多少个？","answer":"9","explanation":"十位不能是 0，有 3 种；个位剩 3 种，共 9 个。"},{"id":"counting-transfer-5","title":"只参加一项","difficulty":"提高","prompt":"喜欢篮球的有 18 人，喜欢足球的有 15 人，两项都喜欢的有 6 人。只喜欢一项的有多少人？","answer":"21","explanation":"只喜欢篮球 18-6=12，只喜欢足球 15-6=9，共 21 人。"},{"id":"counting-transfer-6","title":"综合换乘","difficulty":"挑战","prompt":"用 1、2、3、4 组成没有重复数字的三位数，要求百位是奇数，且个位不是 4，一共有多少个？","answer":"8","explanation":"百位可选 1 或 3。若百位确定，剩 3 个数，个位不能是 4：当 4 还在可选中时个位 2 种，十位 2 种，共每个百位 4 种，两种百位共 8 种。"}]},{"id":"motion","title":"行程问题","practices":[{"id":"motion-1","title":"求路程","difficulty":"基础","prompt":"一辆车每小时行 45 千米，行驶 4 小时，一共行驶多少千米？","answer":"180","explanation":"路程 = 速度 × 时间，45 × 4 = 180 千米。"},{"id":"motion-2","title":"求时间","difficulty":"基础","prompt":"小华每分钟走 70 米，走完 560 米需要多少分钟？","answer":"8","explanation":"时间 = 路程 ÷ 速度，560 ÷ 70 = 8 分钟。"},{"id":"motion-3","title":"相遇时间","difficulty":"进阶","prompt":"甲乙两地相距 720 米，两人同时相向而行，甲每分钟 50 米，乙每分钟 40 米，几分钟相遇？","answer":"8","explanation":"相向而行速度相加，720 ÷ (50 + 40) = 8 分钟。"},{"id":"motion-4","title":"追及时间","difficulty":"提高","prompt":"甲每分钟跑 100 米，乙每分钟跑 80 米，乙先跑 5 分钟，甲几分钟追上乙？","answer":"20","explanation":"乙先跑 80 × 5 = 400 米，甲每分钟多跑 20 米，400 ÷ 20 = 20 分钟。"},{"id":"motion-5","title":"相遇求距离","difficulty":"提高","prompt":"两人同时从两地相向而行，甲每分钟 60 米，乙每分钟 55 米，8 分钟相遇。两地相距多少米？","answer":"920","explanation":"速度和是 115 米/分，8 分钟共走 115 × 8 = 920 米。"},{"id":"motion-6","title":"往返速度","difficulty":"挑战","prompt":"小明上学每分钟走 60 米，15 分钟到校。放学走同一条路用了 18 分钟，放学每分钟走多少米？","answer":"50","explanation":"先求路程：60 × 15 = 900 米；放学速度 = 900 ÷ 18 = 50 米/分。"}]},{"id":"engineering","title":"工程问题","practices":[{"id":"engineering-1","title":"每天做几分之一","difficulty":"基础","prompt":"一项工作，甲单独做 8 天完成。甲每天完成这项工作的几分之几？","answer":"1/8","explanation":"把整项工作看作 1，8 天完成，每天完成 1/8。"},{"id":"engineering-2","title":"合作效率","difficulty":"基础","prompt":"甲每天完成 1/6，乙每天完成 1/3，两人合作每天完成几分之几？","answer":"1/2","explanation":"合作效率相加：1/6 + 1/3 = 1/6 + 2/6 = 3/6 = 1/2。"},{"id":"engineering-3","title":"两人合作几天","difficulty":"进阶","prompt":"甲单独 6 天完成，乙单独 3 天完成。两人合作几天完成？","answer":"2","explanation":"甲每天 1/6，乙每天 1/3，合作每天 1/2，所以 1 ÷ 1/2 = 2 天。"},{"id":"engineering-4","title":"先做再合作","difficulty":"进阶","prompt":"一项工作甲单独 10 天完成，甲先做 2 天，还剩几分之几？","answer":"4/5","explanation":"甲每天做 1/10，2 天做 2/10=1/5，还剩 4/5。"},{"id":"engineering-5","title":"效率比较","difficulty":"提高","prompt":"甲单独 4 天完成，乙单独 12 天完成。甲每天比乙多完成这项工程的几分之几？","answer":"1/6","explanation":"甲每天 1/4=3/12，乙每天 1/12，差是 2/12=1/6。"},{"id":"engineering-6","title":"三人合作","difficulty":"挑战","prompt":"甲 6 天完成，乙 12 天完成，丙 4 天完成。三人合作每天完成几分之几？","answer":"1/2","explanation":"1/6 + 1/12 + 1/4 = 2/12 + 1/12 + 3/12 = 6/12 = 1/2。"}]},{"id":"train-bridge","title":"火车过桥","practices":[{"id":"train-bridge-1","title":"火车过桥","difficulty":"基础","prompt":"一列火车长 100 米，每秒行 20 米，通过 300 米长的桥需要几秒？","answer":"20","explanation":"完全过桥要走 100+300=400 米，400÷20=20 秒。"},{"id":"train-bridge-2","title":"通过路灯","difficulty":"基础","prompt":"一列火车长 180 米，每秒行 30 米，通过路边一根电线杆需要几秒？","answer":"6","explanation":"电线杆看成一个点，火车走过自身长度 180 米即可，180÷30=6 秒。"},{"id":"train-bridge-3","title":"过隧道","difficulty":"进阶","prompt":"火车长 160 米，每秒行 40 米，完全通过 640 米长的隧道要几秒？","answer":"20","explanation":"路程是 160+640=800 米，800÷40=20 秒。"},{"id":"train-bridge-4","title":"反求桥长","difficulty":"进阶","prompt":"火车长 120 米，每秒行 15 米，完全通过一座桥用了 18 秒。这座桥长多少米？","answer":"150","explanation":"18 秒走 15×18=270 米，这是车长加桥长，所以桥长 270-120=150 米。"},{"id":"train-bridge-5","title":"两车相向","difficulty":"提高","prompt":"甲车长 90 米，乙车长 110 米，相向而行速度分别为 15 米/秒和 25 米/秒。从车头相遇到完全错开要几秒？","answer":"5","explanation":"两车合长 200 米，相对速度 40 米/秒，200÷40=5 秒。"},{"id":"train-bridge-6","title":"同向追及","difficulty":"挑战","prompt":"快车长 120 米，每秒 30 米；慢车长 100 米，每秒 20 米。快车从追上慢车车尾到完全超过慢车需要几秒？","answer":"22","explanation":"快车要相对多走两车长度 220 米，相对速度 30-20=10 米/秒，220÷10=22 秒。"}]},{"id":"age","title":"年龄问题","practices":[{"id":"age-1","title":"年龄差","difficulty":"基础","prompt":"姐姐今年 14 岁，妹妹今年 9 岁，5 年后姐姐比妹妹大几岁？","answer":"5","explanation":"年龄差不变，现在相差 14 - 9 = 5 岁，5 年后仍相差 5 岁。"},{"id":"age-2","title":"未来年龄","difficulty":"基础","prompt":"小明今年 8 岁，妈妈今年 34 岁。4 年后两人年龄和是多少？","answer":"50","explanation":"4 年后小明 12 岁，妈妈 38 岁，和是 50 岁。"},{"id":"age-3","title":"几年后倍数","difficulty":"进阶","prompt":"爸爸今年 40 岁，小华今年 10 岁。几年后爸爸年龄是小华的 3 倍？","answer":"5","explanation":"5 年后爸爸 45 岁，小华 15 岁，45 是 15 的 3 倍。"},{"id":"age-4","title":"几年前倍数","difficulty":"提高","prompt":"妈妈今年 32 岁，儿子今年 8 岁。几年前妈妈年龄是儿子的 5 倍？","answer":"2","explanation":"2 年前妈妈 30 岁，儿子 6 岁，30 是 6 的 5 倍。"},{"id":"age-5","title":"年龄和反推","difficulty":"提高","prompt":"兄弟俩今年年龄和是 25 岁，哥哥比弟弟大 5 岁。弟弟今年几岁？","answer":"10","explanation":"弟弟 = (25 - 5) ÷ 2 = 10 岁。"},{"id":"age-6","title":"倍数与差","difficulty":"挑战","prompt":"今年爸爸比儿子大 28 岁，爸爸年龄是儿子的 3 倍。儿子今年几岁？","answer":"14","explanation":"爸爸是儿子的 3 倍，年龄差相当于儿子的 2 倍，28 ÷ 2 = 14。"}]},{"id":"efficiency-transfer","title":"效率换乘站","practices":[{"id":"efficiency-transfer-1","title":"归一速度","difficulty":"基础","prompt":"小明 4 分钟走 240 米，照这样 7 分钟走多少米？","answer":"420","explanation":"每分钟走 240÷4=60 米，7 分钟走 60×7=420 米。"},{"id":"efficiency-transfer-2","title":"相遇效率","difficulty":"基础","prompt":"两人相距 540 米，相向而行，速度分别是 50 米/分和 40 米/分，几分钟相遇？","answer":"6","explanation":"每分钟共同缩短 90 米，540÷90=6 分钟。"},{"id":"efficiency-transfer-3","title":"合作工程","difficulty":"进阶","prompt":"甲 8 天完成，乙 12 天完成。两人合作每天完成这项工程的几分之几？","answer":"5/24","explanation":"甲每天 1/8=3/24，乙每天 1/12=2/24，合计 5/24。"},{"id":"efficiency-transfer-4","title":"追及效率","difficulty":"进阶","prompt":"甲每分钟走 80 米，乙每分钟走 60 米，甲在乙后面 100 米，同向追乙，几分钟追上？","answer":"5","explanation":"每分钟缩短 80-60=20 米，100÷20=5 分钟。"},{"id":"efficiency-transfer-5","title":"先做后合作","difficulty":"提高","prompt":"一项工程甲 10 天完成，乙 15 天完成。甲先做 2 天后，两人合作，还要几天完成？","answer":"4.8","explanation":"甲先做 2/10=1/5，还剩 4/5。合作效率 1/10+1/15=1/6，时间是 4/5÷1/6=24/5 天。"},{"id":"efficiency-transfer-6","title":"综合效率","difficulty":"挑战","prompt":"甲乙两车相距 360 千米相向而行，甲每小时 70 千米，乙每小时 50 千米。相遇后甲继续按原速行驶，到乙出发地还要几小时？","answer":"15/7","explanation":"相遇时间是 360÷(70+50)=3 小时。相遇点到乙出发地还有乙已走过的 50×3=150 千米，甲继续走需要 150÷70=15/7 小时。"}]},{"id":"tree-planting","title":"植树问题","practices":[{"id":"tree-planting-1","title":"两端都种","difficulty":"基础","prompt":"一条路长 24 米，每隔 4 米种一棵树，两端都种，一共种多少棵？","answer":"7","explanation":"间隔数是 24 ÷ 4 = 6，两端都种要加 1，所以是 7 棵。"},{"id":"tree-planting-2","title":"只种一端","difficulty":"基础","prompt":"一条小路长 35 米，每隔 5 米插一面小旗，只在起点插，终点不插，一共插多少面？","answer":"7","explanation":"间隔数是 35 ÷ 5 = 7，只种一端时，数量等于间隔数。"},{"id":"tree-planting-3","title":"两端都不种","difficulty":"进阶","prompt":"一条走廊长 48 米，每隔 6 米放一盆花，两端都不放，一共放多少盆？","answer":"7","explanation":"间隔数是 48 ÷ 6 = 8，两端都不放要减 1，所以是 7 盆。"},{"id":"tree-planting-4","title":"封闭路线","difficulty":"进阶","prompt":"一个圆形跑道长 60 米，每隔 10 米放一个标志桶，一共放多少个？","answer":"6","explanation":"封闭路线数量等于间隔数，60 ÷ 10 = 6。"},{"id":"tree-planting-5","title":"反求间距","difficulty":"提高","prompt":"一条路长 45 米，两端都种树，一共种 10 棵。相邻两棵树相隔多少米？","answer":"5","explanation":"两端都种时，间隔数 = 棵数 - 1 = 9，45 ÷ 9 = 5 米。"},{"id":"tree-planting-6","title":"综合判断","difficulty":"挑战","prompt":"一条路每隔 8 米装一盏灯，两端都装，共装 13 盏。这条路长多少米？","answer":"96","explanation":"两端都装时，间隔数 = 13 - 1 = 12，长度 = 12 × 8 = 96 米。"}]},{"id":"geometry","title":"几何计数","practices":[{"id":"geometry-1","title":"闯关 1","difficulty":"基础","prompt":"一条直线上有 3 个点，可以组成多少条线段？","answer":"3","explanation":"3 个点任选 2 个，可组成 3 条线段。"},{"id":"geometry-2","title":"闯关 2","difficulty":"基础","prompt":"从同一个端点引出 4 条射线，一共可以组成多少个角？","answer":"6","explanation":"任意两条射线组成一个角，以各射线向后组合：3+2+1 = 6 个角。"},{"id":"geometry-3","title":"闯关 3","difficulty":"进阶","prompt":"一个大三角形从顶点向底边引出 2 条线段，把底边分成了 3 个小线段。整个图形中一共有多少个三角形？","answer":"6","explanation":"所有三角形共用一个顶点，三角形的个数等于底边上线段的总数：3+2+1 = 6 个三角形。"},{"id":"geometry-4","title":"闯关 4","difficulty":"进阶","prompt":"由 4 个 1×1 小正方形排成的一行长条中，一共有多少个长方形（包含正方形）？","answer":"10","explanation":"长方形长度可由 1 格、2 格、3 格、4 格组成，分别有 4、3、2、1 个，共有 4+3+2+1 = 10 个长方形。"},{"id":"geometry-5","title":"闯关 5","difficulty":"提高","prompt":"一个 2×2 方格图中，一共有多少个正方形？","answer":"5","explanation":"4 个小正方形加 1 个大正方形，共 5 个。"},{"id":"geometry-6","title":"闯关 6","difficulty":"挑战","prompt":"一个 3×3 方格图中，一共有多少个正方形（包含 1×1、2×2、3×3 的所有正方形）？","answer":"14","explanation":"1×1 正方形有 3×3=9 个，2×2 正方形有 2×2=4 个，3×3 正方形有 1 个，共 9+4+1 = 14 个正方形。"},{"id":"geometry-8","title":"闯关 8","difficulty":"提高","prompt":"一个 2×3 的方格图中，一共有多少个正方形（包含小正方形和大正方形）？","answer":"8","explanation":"1×1 的小正方形有 2×3 = 6 个；2×2 的正方形横向有 2 个位置、纵向有 1 个位置，共 2×1 = 2 个；一共 6+2 = 8 个正方形。"},{"id":"geometry-9","title":"闯关 9","difficulty":"提高","prompt":"一个 2×3 的方格网中，一共有多少个长方形（包含正方形）？","answer":"18","explanation":"长边 3 格包含 3+2+1 = 6 条线段；宽边 2 格包含 2+1 = 3 条线段。根据乘法原理，长方形总数为 6×3 = 18 个。"},{"id":"geometry-11","title":"闯关 11","difficulty":"提高","prompt":"一条直线上有 7 个点，可以组成多少条线段？","answer":"21","explanation":"7 个点任选 2 个，7×6÷2 = 21。"},{"id":"geometry-12","title":"闯关 12","difficulty":"挑战","prompt":"一个 3×3 方格图中，有多少个小正方形？（只数 1×1）","answer":"9","explanation":"每行 3 个，共 3 行，所以有 9 个。"},{"id":"geometry-13","title":"闯关 13","difficulty":"提高","prompt":"一个 4×2 方格图中，有多少个 1×1 的小正方形？","answer":"8","explanation":"横向 4 个，纵向 2 个，共 4×2 = 8。"},{"id":"geometry-14","title":"闯关 14","difficulty":"挑战","prompt":"一条直线上有 8 个点，可以组成多少条线段？","answer":"28","explanation":"8 个点任选 2 个，8×7÷2 = 28。"},{"id":"geometry-15","title":"闯关 15","difficulty":"提高","prompt":"一个 5×1 方格图中，有多少个 1×1 的小正方形？","answer":"5","explanation":"每个小格都是 1 个正方形，一共有 5 个。"}]},{"id":"logic","title":"逻辑推理","practices":[{"id":"logic-1","title":"闯关 1","difficulty":"基础","prompt":"A 不是第一，B 也不是第一，那么第一是谁？（A、B、C 三人中）","answer":"C","explanation":"排除 A 和 B，只剩 C。"},{"id":"logic-2","title":"闯关 2","difficulty":"基础","prompt":"甲比乙快，乙比丙快，谁最慢？","answer":"丙","explanation":"速度最慢的是排在最后的丙。"},{"id":"logic-3","title":"闯关 3","difficulty":"进阶","prompt":"3 个盒子中只有 1 个有奖品。已知红盒没有，蓝盒没有，奖品在哪个盒子？","answer":"黄盒","explanation":"排除红盒和蓝盒，剩下黄盒。"},{"id":"logic-4","title":"闯关 4","difficulty":"进阶","prompt":"小丽不是第三，小华不是第三，那么第三是谁？（小丽、小华、小美）","answer":"小美","explanation":"排除小丽和小华，只剩小美。"},{"id":"logic-5","title":"闯关 5","difficulty":"提高","prompt":"甲比乙重，乙比丙重，谁最重？","answer":"甲","explanation":"由条件可知甲最重。"},{"id":"logic-6","title":"闯关 6","difficulty":"挑战","prompt":"甲不是最后，乙不是第一，丙不是第一，那么第一是谁？","answer":"甲","explanation":"乙和丙都不是第一，所以第一只能是甲。"},{"id":"logic-8","title":"闯关 8","difficulty":"提高","prompt":"A 不是最后，B 不是最后，C 不是最后，那么最后是谁？（A、B、C、D 四人中）","answer":"D","explanation":"排除 A、B、C，最后只能是 D。"},{"id":"logic-9","title":"闯关 9","difficulty":"提高","prompt":"红、黄、蓝三个盒子里只有一个有球。已知红盒有球，哪个盒子有球？","answer":"红盒","explanation":"已知条件直接说明红盒有球。"},{"id":"logic-11","title":"闯关 11","difficulty":"提高","prompt":"甲比乙高，乙比丙高，丙比丁高，谁最矮？","answer":"丁","explanation":"按大小规律排列，丁最矮。"},{"id":"logic-12","title":"闯关 12","difficulty":"挑战","prompt":"A 不是第一，B 不是第二，C 不是第一，那么第一是谁？","answer":"B","explanation":"A 和 C 都不是第一，所以第一只能是 B。"},{"id":"logic-13","title":"闯关 13","difficulty":"提高","prompt":"小军比小强快，小强比小林快，谁最快？","answer":"小军","explanation":"由条件可知小军最快。"},{"id":"logic-14","title":"闯关 14","difficulty":"挑战","prompt":"甲不是第一，乙不是第三，丙不是第一，那么第一是谁？","answer":"乙","explanation":"甲和丙都不是第一，所以第一只能是乙。"},{"id":"logic-15","title":"闯关 15","difficulty":"提高","prompt":"红盒没有奖品，黄盒没有奖品，奖品在哪个盒子？（红、黄、蓝）","answer":"蓝盒","explanation":"排除红盒和黄盒，剩下蓝盒。"}]},{"id":"geometry-counting","title":"图形计数","practices":[{"id":"geometry-counting-1","title":"四点线段","difficulty":"基础","prompt":"一条直线上有 5 个点，一共可以组成多少条线段？","answer":"10","explanation":"任意两个点确定一条线段，按起点数：4+3+2+1=10。"},{"id":"geometry-counting-2","title":"数角","difficulty":"基础","prompt":"从同一个顶点射出 4 条射线，一共形成多少个角？","answer":"6","explanation":"任意两条射线形成一个角，3+2+1=6 个。"},{"id":"geometry-counting-3","title":"分割三角形","difficulty":"进阶","prompt":"一个大三角形从顶点向底边画 4 条分割线，把底边分成 5 段。一共有多少个三角形？","answer":"15","explanation":"底边连续 1 段有 5 个，连续 2 段有 4 个，……连续 5 段有 1 个，共 15 个。"},{"id":"geometry-counting-4","title":"一行方格","difficulty":"进阶","prompt":"一行 4 个小正方形组成的长方形中，一共有多少个长方形？","answer":"10","explanation":"长度为 1 格有 4 个，2 格有 3 个，3 格有 2 个，4 格有 1 个，共 10 个。"},{"id":"geometry-counting-5","title":"方格长方形","difficulty":"提高","prompt":"2 行 2 列小方格组成的正方形中，一共有多少个长方形？","answer":"9","explanation":"横向选两条竖线有 3 种，纵向选两条横线有 3 种，共 3×3=9。"},{"id":"geometry-counting-6","title":"综合方格","difficulty":"挑战","prompt":"2 行 3 列小方格组成的长方形中，一共有多少个正方形？","answer":"8","explanation":"1×1 正方形有 6 个，2×2 正方形有 2 个，共 8 个。"}]},{"id":"parity-divisibility","title":"奇偶性与整除","practices":[{"id":"parity-divisibility-1","title":"奇偶加法","difficulty":"基础","prompt":"偶数 + 奇数 的结果是奇数还是偶数？","answer":"奇数","explanation":"偶数不改变奇偶性，加上一个奇数后结果是奇数。"},{"id":"parity-divisibility-2","title":"奇偶乘法","difficulty":"基础","prompt":"奇数 × 偶数 的结果是奇数还是偶数？","answer":"偶数","explanation":"乘数中有偶数，表示可以分成成对的组，结果一定是偶数。"},{"id":"parity-divisibility-3","title":"能否被 3 整除","difficulty":"进阶","prompt":"三位数 52□ 能被 3 整除，方框里最小能填的数字是多少？","answer":"2","explanation":"一个数能被 3 整除，其各位数字之和必是 3 的倍数。5+2=7，7+2=9 是 3 的倍数，所以方框里最小填 2。"},{"id":"parity-divisibility-4","title":"能否被 9 整除","difficulty":"进阶","prompt":"四位数 78□2 能被 9 整除，方框里的数字是多少？","answer":"1","explanation":"一个数能被 9 整除，其各位数字之和必是 9 的倍数。7+8+2=17，17+1=18 是 9 的倍数，所以方框里只能填 1。"},{"id":"parity-divisibility-5","title":"不可能性","difficulty":"提高","prompt":"3 个偶数和 4 个奇数相加，结果是奇数还是偶数？","answer":"偶数","explanation":"偶数不影响奇偶性；4 个奇数相加是偶数，所以总和是偶数。"},{"id":"parity-divisibility-6","title":"填数字","difficulty":"挑战","prompt":"三位数 45□ 能被 5 整除，方框里可以填几个不同数字？","answer":"2","explanation":"能被 5 整除的数个位只能是 0 或 5，所以可填 0、5，共 2 个。"}]}],"chapter-03":[{"id":"factors-multiples","title":"倍数与因数","practices":[{"id":"factors-multiples-1","title":"闯关 1","difficulty":"基础","prompt":"自然数 12 一共有多少个不同的正因数？","answer":"6","explanation":"12 的全部正因数是 1、2、3、4、6、12，一共有 6 个因数。"},{"id":"factors-multiples-2","title":"闯关 2","difficulty":"基础","prompt":"3 是 14 的因数吗？回答“是”或“不是”。","answer":"不是","explanation":"14 ÷ 3 有余数，所以 3 不是 14 的因数。"},{"id":"factors-multiples-3","title":"闯关 3","difficulty":"进阶","prompt":"20 的一个因数是 4 还是 6？","answer":"4","explanation":"20 ÷ 4 = 5，没有余数；20 ÷ 6 有余数。"},{"id":"factors-multiples-4","title":"闯关 4","difficulty":"进阶","prompt":"在 50 以内，既是 6 的倍数又是 8 的倍数的最大两位数是多少？","answer":"48","explanation":"6 和 8 的最小公倍数是 24。50 以内 24 的倍数有 24 和 48，其中最大的是 48。"},{"id":"factors-multiples-5","title":"闯关 5","difficulty":"提高","prompt":"24 的最小因数是多少？","answer":"1","explanation":"任何自然数的最小因数都是 1。"},{"id":"factors-multiples-6","title":"闯关 6","difficulty":"提高","prompt":"除 24 本身以外，24 的最大因数是多少？","answer":"12","explanation":"24 的因数从小到大是 1、2、3、4、6、8、12、24。除去自身外，最大的因数是 24÷2 = 12。"},{"id":"factors-multiples-7","title":"闯关 7","difficulty":"挑战","prompt":"一个数同时是 4 和 5 的倍数，它一定是几的倍数？","answer":"20","explanation":"同时是 4 和 5 的倍数时，一定是 20 的倍数。"},{"id":"factors-multiples-8","title":"闯关 8","difficulty":"挑战","prompt":"30 以内既是 2 的倍数又是 3 的倍数的最小数是多少？","answer":"6","explanation":"同时是 2 和 3 的倍数的最小数是 6。"},{"id":"factors-multiples-9","title":"闯关 9","difficulty":"提高","prompt":"一个数的真因数（除去自身外的所有因数）之和等于它本身，叫完全数。在 10 以内的自然数中，唯一的完全数是多少？","answer":"6","explanation":"6 除去自身外的真因数是 1、2、3，且 1+2+3 = 6，因数和等于自身，因此 6 是完全数。"},{"id":"factors-multiples-10","title":"闯关 10","difficulty":"挑战","prompt":"40 以内既是 4 的倍数又是 6 的倍数的最小数是多少？","answer":"12","explanation":"同时是 4 和 6 的倍数的最小数是 12。"}]},{"id":"ratio-proportion","title":"比和比例","practices":[{"id":"ratio-proportion-1","title":"闯关 1","difficulty":"基础","prompt":"8 和 4 的最简整数比是多少？","answer":"2:1","explanation":"8:4 化简为 2:1。"},{"id":"ratio-proportion-2","title":"闯关 2","difficulty":"基础","prompt":"10 和 5 的最简整数比是多少？","answer":"2:1","explanation":"10:5=2:1。"},{"id":"ratio-proportion-3","title":"闯关 3","difficulty":"进阶","prompt":"把 15 按 2:3 分成两份，较大的一份是多少？","answer":"9","explanation":"总份数 5，每份 3，较大一份是 3 份。"},{"id":"ratio-proportion-4","title":"闯关 4","difficulty":"进阶","prompt":"把 20 按 1:4 分成两份，较小的一份是多少？","answer":"4","explanation":"总份数 5，每份 4，较小一份 1 份。"},{"id":"ratio-proportion-5","title":"闯关 5","difficulty":"进阶","prompt":"已知甲数与乙数的比是 2:3，乙数与丙数的比是 3:4。若三数之和为 45，那么丙数是多少？","answer":"20","explanation":"乙数份数相同，连比甲:乙:丙 ＝ 2:3:4；总份数 ＝ 2＋3＋4 ＝ 9 份；每份 45÷9 ＝ 5；丙数占 4 份，即 4 × 5 ＝ 20。"},{"id":"ratio-proportion-6","title":"闯关 6","difficulty":"提高","prompt":"12:18 的最简整数比是多少？","answer":"2:3","explanation":"同时除以最大公因数 6，得 2:3。"},{"id":"ratio-proportion-7","title":"闯关 7","difficulty":"提高","prompt":"兄弟二人共有 60 枚纪念币，原来哥哥与弟弟的枚数比是 3:2。哥哥送给弟弟多少枚后，两人的枚数比变为 1:1？","answer":"6","explanation":"总枚数 60 不变；原来哥哥有 60 × 3/5 ＝ 36 枚，弟弟有 24 枚；变为 1:1 后各 30 枚；哥哥送出 36 － 30 ＝ 6 枚。"},{"id":"ratio-proportion-8","title":"闯关 8","difficulty":"提高","prompt":"18:27 的最简整数比中，后项是多少？","answer":"3","explanation":"18 与 27 同时除以最大公因数 9 得最简整数比 2:3，后项是 3。"},{"id":"ratio-proportion-9","title":"闯关 9","difficulty":"挑战","prompt":"甲乙两个长方形面积相等。已知甲与乙的长之比为 4:5，那么甲与乙的宽之比化为最简整数比后，前项是多少？","answer":"5","explanation":"面积相等时宽与长成反比：宽之比 ＝ 1/4 : 1/5 ＝ 5:4，最简整数比的前项是 5。"},{"id":"ratio-proportion-10","title":"闯关 10","difficulty":"挑战","prompt":"甲、乙两个仓库共存粮 120 吨，存粮吨数的比是 5:3。甲仓库比乙仓库多存粮多少吨？","answer":"30","explanation":"总份数是 5+3 = 8 份，每份为 120÷8 = 15 吨。甲比乙多 5-3 = 2 份，所以多存粮 15×2 = 30 吨。"}]},{"id":"pigeonhole-intro","title":"抽屉原理入门","practices":[{"id":"pigeonhole-intro-1","title":"闯关 1","difficulty":"基础","prompt":"4 个球放进 3 个盒子，是否一定有一个盒子至少 2 个球？","answer":"是","explanation":"每盒最多 1 个只能放 3 个球，所以一定有一盒至少 2 个。"},{"id":"pigeonhole-intro-2","title":"闯关 2","difficulty":"基础","prompt":"2 只小鸟飞到 2 棵树上，是否一定有一棵树至少 2 只？","answer":"不是","explanation":"可以每棵树 1 只，不一定有 2 只。"},{"id":"pigeonhole-intro-3","title":"闯关 3","difficulty":"进阶","prompt":"6 个学生分到 5 张桌子，是否一定有一张桌子至少坐 2 人？","answer":"是","explanation":"每桌最多 1 人只能坐 5 人，所以一定有一桌至少 2 人。"},{"id":"pigeonhole-intro-4","title":"闯关 4","difficulty":"进阶","prompt":"3 个数除以 2，是否一定有两个数余数相同？","answer":"是","explanation":"余数只有 0、1 两类，3 个数一定有两数同类。"},{"id":"pigeonhole-intro-5","title":"闯关 5","difficulty":"提高","prompt":"7 本书放进 3 个书包，是否一定有一个书包至少装 3 本？","answer":"是","explanation":"若每包最多 2 本，最多装 6 本，不够 7 本。"},{"id":"pigeonhole-intro-6","title":"闯关 6","difficulty":"提高","prompt":"5 个整数除以 4，是否一定有两个数余数相同？","answer":"是","explanation":"余数只有 0、1、2、3 四类，5 个数一定有两数同类。"},{"id":"pigeonhole-intro-7","title":"闯关 7","difficulty":"挑战","prompt":"10 支笔放进 4 个盒子，是否一定有一个盒子至少 3 支？","answer":"是","explanation":"若每盒最多 2 支，最多只能放 8 支。"},{"id":"pigeonhole-intro-8","title":"闯关 8","difficulty":"挑战","prompt":"6 个小朋友出生月份只有 5 种可能时，是否一定有两人同月？","answer":"是","explanation":"6 人放入 5 个月份类中，至少两人同类。"},{"id":"pigeonhole-intro-9","title":"闯关 9","difficulty":"提高","prompt":"8 个苹果放进 3 个篮子，是否一定有一个篮子至少 3 个？","answer":"是","explanation":"每篮最多 2 个只能放 6 个，不够 8 个。"},{"id":"pigeonhole-intro-10","title":"闯关 10","difficulty":"挑战","prompt":"13 个人按生肖分 12 类，是否一定有两人同生肖？","answer":"是","explanation":"13 人放入 12 类，至少有两人同类。"}]},{"id":"recurrence-intro","title":"递推与迭代初步","practices":[{"id":"recurrence-intro-1","title":"闯关 1","difficulty":"基础","prompt":"从 2 开始每次加 3，第三个数是多少？","answer":"8","explanation":"2、5、8。"},{"id":"recurrence-intro-2","title":"闯关 2","difficulty":"基础","prompt":"从 1 开始每次加 5，第四个数是多少？","answer":"16","explanation":"1、6、11、16。"},{"id":"recurrence-intro-3","title":"闯关 3","difficulty":"进阶","prompt":"从 3 开始每次乘 2，第三个数是多少？","answer":"12","explanation":"3、6、12。"},{"id":"recurrence-intro-4","title":"闯关 4","difficulty":"进阶","prompt":"数列的前两项都是 1，从第三项开始每一项都等于前两项的和：1、1、2、3、5……这个数列的第 7 项是多少？","answer":"13","explanation":"第 1 项为 1，第 2 项为 1；第 3 项 1+1=2；第 4 项 1+2=3；第 5 项 2+3=5；第 6 项 3+5=8；第 7 项 5+8=13。"},{"id":"recurrence-intro-5","title":"闯关 5","difficulty":"提高","prompt":"第一个数是 4，后一个数等于前一个数加 2，第五个数是多少？","answer":"12","explanation":"4、6、8、10、12。"},{"id":"recurrence-intro-6","title":"闯关 6","difficulty":"提高","prompt":"第一个数是 1，后一个数等于前一个数乘 2，第六个数是多少？","answer":"32","explanation":"1、2、4、8、16、32。"},{"id":"recurrence-intro-7","title":"闯关 7","difficulty":"挑战","prompt":"从 1 开始，每次先乘 2 再加 1，第四个数是多少？","answer":"15","explanation":"1、3、7、15。"},{"id":"recurrence-intro-8","title":"闯关 8","difficulty":"挑战","prompt":"从 2 开始，每次先加 1 再乘 2，第三个数是多少？","answer":"14","explanation":"2，6，14。"},{"id":"recurrence-intro-9","title":"闯关 9","difficulty":"提高","prompt":"从 2 开始，每次乘 2，第四个数是多少？","answer":"16","explanation":"2、4、8、16。"},{"id":"recurrence-intro-10","title":"闯关 10","difficulty":"挑战","prompt":"第一天 1 朵花，以后每天是前一天的 2 倍，第 5 天有几朵？","answer":"16","explanation":"1、2、4、8、16。"}]},{"id":"plan-design","title":"方案设计题","practices":[{"id":"plan-design-1","title":"闯关 1","difficulty":"基础","prompt":"12 元钱，每支笔 3 元，最多买几支？","answer":"4","explanation":"12÷3=4。"},{"id":"plan-design-2","title":"闯关 2","difficulty":"基础","prompt":"甲方案用 2 个箱子，乙方案用 5 个箱子，哪个更省箱子？回答“甲”或“乙”。","answer":"甲","explanation":"2 个箱子更少。"},{"id":"plan-design-3","title":"闯关 3","difficulty":"进阶","prompt":"18 个苹果，每袋装 6 个，需要几袋？","answer":"3","explanation":"18÷6=3。"},{"id":"plan-design-4","title":"闯关 4","difficulty":"进阶","prompt":"三种方案所需时间是 9、7、8 分钟，最优方案是第几种？","answer":"2","explanation":"7 分钟最短。"},{"id":"plan-design-5","title":"闯关 5","difficulty":"提高","prompt":"24 个球，每盒装 8 个，需要几盒？","answer":"3","explanation":"24÷8=3。"},{"id":"plan-design-6","title":"闯关 6","difficulty":"提高","prompt":"甲方案要 12 元，乙方案要 10 元，哪个更省钱？","answer":"乙","explanation":"10 元更少。"},{"id":"plan-design-7","title":"闯关 7","difficulty":"挑战","prompt":"30 个零件，每箱装 5 个，需要几箱？","answer":"6","explanation":"30÷5=6。"},{"id":"plan-design-8","title":"闯关 8","difficulty":"挑战","prompt":"三种方案费用分别是 16、13、15 元，最优方案是第几种？","answer":"2","explanation":"13 元最少。"},{"id":"plan-design-9","title":"闯关 9","difficulty":"提高","prompt":"买 3 元票 4 张共 12 元，买 5 元票 2 张共 10 元，哪种更便宜？","answer":"5元票2张","explanation":"10 元比 12 元少。"},{"id":"plan-design-10","title":"闯关 10","difficulty":"挑战","prompt":"方案 A 共 24 元，方案 B 共 21 元，方案 C 共 23 元，最省钱的是哪个？","answer":"方案B","explanation":"21 元最少。"}]},{"id":"square-array","title":"方阵问题","practices":[{"id":"square-array-1","title":"闯关 1","difficulty":"基础","prompt":"阅兵式上，仪仗队员排成 6 行 6 列的正方形实心方阵，这个方阵一共有多少名队员？","answer":"36","explanation":"实心方阵总人数 ＝ 每边人数 × 每边人数，即 6 × 6 ＝ 36 名。"},{"id":"square-array-2","title":"闯关 2","difficulty":"基础","prompt":"一个 7 行 7 列的正方形方阵，最外层一周一共有多少个点？","answer":"24","explanation":"最外层总点数 ＝ (每边点数 - 1) × 4。四个角上的点各被两条边共用，所以 (7 - 1) × 4 ＝ 24 个。"},{"id":"square-array-3","title":"闯关 3","difficulty":"进阶","prompt":"一个实心方阵的最外层一周共有 28 盆鲜花，这个方阵每边摆了多少盆花？","answer":"8","explanation":"已知最外层总数逆求每边点数：每边点数 ＝ 最外层总数 ÷ 4 ＋ 1，即 28 ÷ 4 ＋ 1 ＝ 8 盆。"},{"id":"square-array-4","title":"闯关 4","difficulty":"进阶","prompt":"一个 5 行 5 列的实心方阵，若要在最外层再向外围上一层形成新的方阵，需要增加多少个点？","answer":"24","explanation":"原方阵每边 5 个点，向外扩一层后新方阵每边为 5 ＋ 2 ＝ 7 个点；新增点数 ＝ (7 - 1) × 4 ＝ 24 个。"},{"id":"square-array-5","title":"闯关 5","difficulty":"进阶","prompt":"体操队员排成一个两层空心方阵，最外层每边 8 人，这个两层空心方阵一共有多少人？","answer":"48","explanation":"外层人数 (8 - 1) × 4 ＝ 28 人；内层每边 8 - 2 ＝ 6 人，内层人数 (6 - 1) × 4 ＝ 20 人；总人数 28 ＋ 20 ＝ 48 人（也可由大实心 64 减小实心 16 得到）。"},{"id":"square-array-6","title":"闯关 6","difficulty":"提高","prompt":"用若干块地砖刚好铺成一个 8 行 8 列的实心方阵。若要扩充成一个 9 行 9 列的方阵，还需增加多少块地砖？","answer":"17","explanation":"扩充一层只需要补全相邻的一行和一列以及角上一块：新方阵 9×9 ＝ 81 块，原方阵 8×8 ＝ 64 块，还需增加 81 － 64 ＝ 17 块（即 8 × 2 ＋ 1 ＝ 17 块）。"},{"id":"square-array-7","title":"闯关 7","difficulty":"提高","prompt":"一个实心点阵由 100 个点组成，如果剥去它最外层的一周点，剩下的内部方阵共有多少个点？","answer":"64","explanation":"原方阵 100 个点，每边为 10 个；剥去最外层后，内层每边减少 2 个变为 8 个；内部剩下 8 × 8 ＝ 64 个点。"},{"id":"square-array-8","title":"闯关 8","difficulty":"提高","prompt":"花坛摆放了三层空心花盆方阵，已知最外层每边有 10 盆花，那么最内层一周有多少盆花？","answer":"20","explanation":"方阵相邻两层人数恒差 8 人；最外层人数 ＝ (10 - 1) × 4 ＝ 36 盆；中间层 ＝ 36 － 8 ＝ 28 盆；最内层 ＝ 28 － 8 ＝ 20 盆。"},{"id":"square-array-9","title":"闯关 9","difficulty":"挑战","prompt":"排成 6 行 6 列的实心方队全部解散后，改排成每行 4 人的长方形队列，可以排成多少行？","answer":"9","explanation":"总人数总量守恒：6 × 6 ＝ 36 人；改排成每行 4 人的长方形队伍，行数 ＝ 36 ÷ 4 ＝ 9 行。"},{"id":"square-array-10","title":"闯关 10","difficulty":"挑战","prompt":"同学们排成一个实心方阵，还多出 5 人；如果横竖各增加一排排成大实心方阵，则还缺少 8 人。原来一共有多少名同学？","answer":"41","explanation":"横竖各增加一排共需增加 5 ＋ 8 ＝ 13 人；增加一排需 (原每边人数 × 2 ＋ 1) ＝ 13，得原每边人数 ＝ (13 - 1) ÷ 2 ＝ 6 人；原来共有 6 × 6 ＋ 5 ＝ 41 人。"}]},{"id":"tiered-pricing","title":"分段计费","practices":[{"id":"tiered-pricing-1","title":"闯关 1","difficulty":"基础","prompt":"前 1 小时 6 元，之后每小时 2 元，停 2 小时共多少元？","answer":"8","explanation":"6+2=8。"},{"id":"tiered-pricing-2","title":"闯关 2","difficulty":"基础","prompt":"前 2 千克每千克 5 元，之后每千克 3 元，买 2 千克共多少元？","answer":"10","explanation":"2×5=10。"},{"id":"tiered-pricing-3","title":"闯关 3","difficulty":"进阶","prompt":"前 2 千克每千克 4 元，超过部分每千克 2 元，买 4 千克共多少元？","answer":"12","explanation":"前 2 千克 8 元，后 2 千克 4 元。"},{"id":"tiered-pricing-4","title":"闯关 4","difficulty":"进阶","prompt":"前 3 本每本 5 元，之后每本 3 元，买 4 本共多少元？","answer":"18","explanation":"前 3 本 15 元，后 1 本 3 元。"},{"id":"tiered-pricing-5","title":"闯关 5","difficulty":"提高","prompt":"前 2 小时每小时 3 元，之后每小时 1 元，停 5 小时共多少元？","answer":"9","explanation":"前 2 小时 6 元，后 3 小时 3 元。"},{"id":"tiered-pricing-6","title":"闯关 6","difficulty":"提高","prompt":"前 1 千克 8 元，之后每千克 5 元，买 3 千克共多少元？","answer":"18","explanation":"前 1 千克 8 元，后 2 千克 10 元。"},{"id":"tiered-pricing-7","title":"闯关 7","difficulty":"挑战","prompt":"出租车起步价 3 千米以内收费 10 元，超过 3 千米的部分每千米收 2 元。小明一次乘车共付费 24 元，他最多乘车行驶了多少千米？","answer":"10","explanation":"超出起步价的费用为 24-10 = 14 元。超出 3 千米后行驶了 14÷2 = 7 千米。总里程为 3+7 = 10 千米。"},{"id":"tiered-pricing-8","title":"闯关 8","difficulty":"挑战","prompt":"前 3 件每件 7 元，之后每件 4 元，买 6 件共多少元？","answer":"33","explanation":"前 3 件 21 元，后 3 件 12 元。"},{"id":"tiered-pricing-9","title":"闯关 9","difficulty":"提高","prompt":"前 5 千米每千米 2 元，超过部分每千米 3 元，走 7 千米共多少元？","answer":"16","explanation":"前 5 千米 10 元，超过 2 千米 6 元，共 16 元。"},{"id":"tiered-pricing-10","title":"闯关 10","difficulty":"挑战","prompt":"前 10 度每度 1 元，超过部分每度 2 元，用 14 度共多少元？","answer":"18","explanation":"前 10 度 10 元，超过 4 度 8 元，共 18 元。"}]},{"id":"prime-factorization","title":"分解质因数","practices":[{"id":"prime-factorization-1","title":"闯关 1","difficulty":"基础","prompt":"把 24 分解质因数写成连乘形式，其中最大的质因数是多少？","answer":"3","explanation":"短除法分解：24 ＝ 2 × 2 × 2 × 3。分解出的质因数有 2 和 3，其中最大的质因数是 3。"},{"id":"prime-factorization-2","title":"闯关 2","difficulty":"基础","prompt":"把 60 分解质因数后，包含多少个不同的质因数？","answer":"3","explanation":"60 ＝ 2 × 2 × 3 × 5，不同质因数有 2、3、5 共 3 个。"},{"id":"prime-factorization-3","title":"闯关 3","difficulty":"进阶","prompt":"72 分解质因数后写成连乘积（72 ＝ 2×2×2×3×3），其中质因数 2 出现了多少次？","answer":"3","explanation":"72 ＝ 2 × 2 × 2 × 3 × 3，质因数 2 连续出现了 3 次。"},{"id":"prime-factorization-4","title":"闯关 4","difficulty":"进阶","prompt":"自然数 84 的所有质因数的和是多少？（每个质因数按其分解次数重复累加）","answer":"16","explanation":"84 ＝ 2 × 2 × 3 × 7；各质因数累加和 ＝ 2 ＋ 2 ＋ 3 ＋ 7 ＝ 16。"},{"id":"prime-factorization-5","title":"闯关 5","difficulty":"进阶","prompt":"两个质数的和是 39，这两个质数的乘积是多少？","answer":"74","explanation":"两质数之和 39 是奇数，必为一奇一偶；唯一的偶质数是 2，另一个质数是 39 － 2 ＝ 37；两数之积 ＝ 2 × 37 ＝ 74。"},{"id":"prime-factorization-6","title":"闯关 6","difficulty":"提高","prompt":"一个两位数分解质因数后是三个连续自然数的乘积，这个两位数是多少？","answer":"60","explanation":"连续自然数乘积：3 × 4 × 5 ＝ 60；60 分解质因数 ＝ 2 × 2 × 3 × 5，是符合条件的唯一两位数。"},{"id":"prime-factorization-7","title":"闯关 7","difficulty":"提高","prompt":"要把 45 乘以一个最小的正整数，使它们的乘积成为一个完全平方数，这个最小正整数是多少？","answer":"5","explanation":"完全平方数各质因数指数均为偶数；45 ＝ 3 × 3 × 5，质因数 5 只有 1 个，需再补乘一个 5 组成 45 × 5 ＝ 225 ＝ 15×15。"},{"id":"prime-factorization-8","title":"闯关 8","difficulty":"提高","prompt":"计算从 1 乘到 15 的乘积（1×2×3×...×15），末尾连续有多少个 0？","answer":"3","explanation":"末尾 0 的个数取决于质因数 2 和 5 的对数；1 到 15 中质因数 5 分别来自 5、10、15，共有 3 个 5，因此末尾连续有 3 个 0。"},{"id":"prime-factorization-9","title":"闯关 9","difficulty":"挑战","prompt":"自然数 N 分解质因数后为 N ＝ 2 × 3 × 3 × 5，那么 N 一共有多少个正因数？","answer":"12","explanation":"因数个数定理：各质因数指数加 1 后连乘。N ＝ 2¹ × 3² × 5¹，因数个数 ＝ (1+1) × (2+1) × (1+1) ＝ 2 × 3 × 2 ＝ 12 个。"},{"id":"prime-factorization-10","title":"闯关 10","difficulty":"挑战","prompt":"两个正整数的最大公因数是 6，最小公倍数是 72，且两数均不为 6。这两个数中较大的是多少？","answer":"24","explanation":"两数设为 6a 和 6b（a, b 互质）；LCM ＝ 6ab ＝ 72 得 ab ＝ 12；因两数不为 6，a、b 不能为 1，故 a＝3，b＝4；两数为 18 和 24，较大数为 24。"}]},{"id":"case-analysis-intro","title":"分类讨论入门","practices":[{"id":"case-analysis-intro-1","title":"闯关 1","difficulty":"基础","prompt":"按奇偶分类，一个数可以分成几类？","answer":"2","explanation":"奇数一类，偶数一类。"},{"id":"case-analysis-intro-2","title":"闯关 2","difficulty":"基础","prompt":"十位只能是 3 或 4，这是几种情况？","answer":"2","explanation":"共有两种。"},{"id":"case-analysis-intro-3","title":"闯关 3","difficulty":"进阶","prompt":"把 1、2、3、4 按奇偶分类，共几类？","answer":"2","explanation":"奇数类和偶数类。"},{"id":"case-analysis-intro-4","title":"闯关 4","difficulty":"进阶","prompt":"某题分成甲、乙两种情况，甲有 5 种，乙有 2 种，共几种？","answer":"7","explanation":"5+2=7。"},{"id":"case-analysis-intro-5","title":"闯关 5","difficulty":"提高","prompt":"一个数的个位可能是 0、2、4、6、8，可分成几种情况？","answer":"5","explanation":"共有 5 种可能。"},{"id":"case-analysis-intro-6","title":"闯关 6","difficulty":"提高","prompt":"某题分三类，分别有 2、3、4 种，共多少种？","answer":"9","explanation":"2+3+4=9。"},{"id":"case-analysis-intro-7","title":"闯关 7","difficulty":"挑战","prompt":"一个数个位可能是 1、3、5、7、9，可分成几种情况？","answer":"5","explanation":"共有 5 种。"},{"id":"case-analysis-intro-8","title":"闯关 8","difficulty":"挑战","prompt":"某题分两大类，第一类 6 种，第二类 8 种，共几种？","answer":"14","explanation":"6+8=14。"},{"id":"case-analysis-intro-9","title":"闯关 9","difficulty":"提高","prompt":"某题分四类，分别有 1、2、3、4 种，共多少种？","answer":"10","explanation":"1+2+3+4=10。"},{"id":"case-analysis-intro-10","title":"闯关 10","difficulty":"挑战","prompt":"一个数的十位可能是 1、2、3，个位可能是 0 或 5，可分成多少种情况？","answer":"6","explanation":"3×2=6。"}]},{"id":"work-problems","title":"工程问题","practices":[{"id":"work-problems-1","title":"闯关 1","difficulty":"基础","prompt":"空间站太阳能翼板维护工程，甲工程师单独检修需要 6 天完成。他平均每天完成这项工程的几分之几？","answer":"1/6","explanation":"把整个工程总量看作单位“1”，工作效率 ＝ 工作总量 ÷ 工作时间，即 1 ÷ 6 ＝ 1/6。"},{"id":"work-problems-2","title":"闯关 2","difficulty":"基础","prompt":"维修空间实验室管道，甲队每天完成全工程的 1/4，乙队每天完成 1/12。两队合作一天共完成几分之几？","answer":"1/3","explanation":"合作工作效率 ＝ 各队效率之和，即 1/4 ＋ 1/12 ＝ 3/12 ＋ 1/12 ＝ 4/12 ＝ 1/3。"},{"id":"work-problems-3","title":"闯关 3","difficulty":"进阶","prompt":"一项太空舱段组装任务，甲组独做需要 6 天，乙组独做需要 12 天。两组合作需要多少天完成？","answer":"4","explanation":"甲组效率 1/6，乙组效率 1/12；合作效率 ＝ 1/6 ＋ 1/12 ＝ 1/4；合作工期 ＝ 1 ÷ (1/4) ＝ 4 天。"},{"id":"work-problems-4","title":"闯关 4","difficulty":"进阶","prompt":"空间探测器轨道计算任务，主算法单独运行需要 10 小时完成。先单独运行 4 小时后，还剩下全部计算量的几分之几未完成？","answer":"3/5","explanation":"4 小时完成 4 × (1/10) ＝ 2/5；剩余未完成部分 ＝ 1 － 2/5 ＝ 3/5。"},{"id":"work-problems-5","title":"闯关 5","difficulty":"进阶","prompt":"铺设一条长 240 米的空间站内部通信光缆，甲队每天铺设 12 米，乙队每天铺设 8 米。两队从两端同时施工，几天可以铺设完成？","answer":"12","explanation":"两队合作每天总进度 ＝ 12 ＋ 8 ＝ 20 米；打通所需天数 ＝ 240 ÷ 20 ＝ 12 天。"},{"id":"work-problems-6","title":"闯关 6","difficulty":"提高","prompt":"一项数据校验任务，甲乙两台超级计算机合作需要 6 小时完成。已知甲机单独运行需要 10 小时，那么乙机单独运行需要多少小时？","answer":"15","explanation":"合作总效率 1/6，甲机效率 1/10；乙机效率 ＝ 1/6 － 1/10 ＝ 5/30 － 3/30 ＝ 1/15；乙机独做所需时间 ＝ 1 ÷ (1/15) ＝ 15 小时。"},{"id":"work-problems-7","title":"闯关 7","difficulty":"提高","prompt":"加工一批精密星载仪器，甲技师独做需 8 天完成，乙技师独做需 12 天完成。在相同工作时间内，甲与乙完成的工作量最简整数比中，前项是多少？","answer":"3","explanation":"工作效率之比与完成时间成反比：甲效率为 1/8，乙为 1/12；工作量之比 ＝ 1/8 : 1/12 ＝ 3 : 2，前项是 3。"},{"id":"work-problems-8","title":"闯关 8","difficulty":"提高","prompt":"一项核心系统代码重构，甲专家单独重构需要 4 小时，乙专家单独需 6 小时，丙专家需 12 小时。三人协作同时开展，需要多少小时完成？","answer":"2","explanation":"三人合作效率之和 ＝ 1/4 ＋ 1/6 ＋ 1/12 ＝ 3/12 ＋ 2/12 ＋ 1/12 ＝ 6/12 ＝ 1/2；所需时间 ＝ 1 ÷ (1/2) ＝ 2 小时。"},{"id":"work-problems-9","title":"闯关 9","difficulty":"挑战","prompt":"清运空间碎片，清运船 A 单独清运需 4 天，清运船 B 单独需 6 天。两船轮流清运，船 A 工作一天后船 B 工作一天，交替循环进行，完成全部清运一共需要多少天？","answer":"5","explanation":"以 2 天为一个交替周期，一个周期完成 1/4 ＋ 1/6 ＝ 5/12；经过 2 个周期（4天）共完成 5/12 × 2 ＝ 10/12 ＝ 5/6；剩下 1 － 5/6 ＝ 1/6；第 5 天轮到船 A（一天可做 1/4 > 1/6），所以在第 5 天内彻底完成，共计 5 天。"},{"id":"work-problems-10","title":"闯关 10","difficulty":"挑战","prompt":"制造实验舱外防护外壳，甲车间独做需 12 天，乙车间独做需 18 天。两车间合作若干天后，乙车间因设备检修调离，剩下由甲车间单独工作 2 天全部完成。乙车间实际参与合作了多少天？","answer":"6","explanation":"甲车间最后 2 天完成工作量 ＝ 2 × (1/12) ＝ 1/6；两车间合作完成的工作总量 ＝ 1 － 1/6 ＝ 5/6；合作每日工作效率 ＝ 1/12 ＋ 1/18 ＝ 3/36 ＋ 2/36 ＝ 5/36；乙车间合作工作天数 ＝ (5/6) ÷ (5/36) ＝ 6 天。"}]},{"id":"unitary-method","title":"归一问题","practices":[{"id":"unitary-method-1","title":"闯关 1","difficulty":"基础","prompt":"2 个苹果 6 元，1 个苹果多少元？","answer":"3","explanation":"6÷2=3。"},{"id":"unitary-method-2","title":"闯关 2","difficulty":"基础","prompt":"5 支笔 15 元，1 支笔多少元？","answer":"3","explanation":"15÷5=3。"},{"id":"unitary-method-3","title":"闯关 3","difficulty":"进阶","prompt":"3 本本子 12 元，6 本本子多少元？","answer":"24","explanation":"先求每本 4 元，再算 6 本。"},{"id":"unitary-method-4","title":"闯关 4","difficulty":"进阶","prompt":"4 千克苹果 20 元，7 千克苹果多少元？","answer":"35","explanation":"先求每千克 5 元，再算 7 千克。"},{"id":"unitary-method-5","title":"闯关 5","difficulty":"提高","prompt":"6 人 3 天做 18 个零件，1 人 1 天做几个？","answer":"1","explanation":"18÷6÷3=1。"},{"id":"unitary-method-6","title":"闯关 6","difficulty":"提高","prompt":"2 小时走 14 千米，5 小时走多少千米？","answer":"35","explanation":"先求每小时 7 千米，再乘 5。"},{"id":"unitary-method-7","title":"闯关 7","difficulty":"挑战","prompt":"8 本书 56 元，12 本书多少元？","answer":"84","explanation":"先求每本 7 元，再求 12 本。"},{"id":"unitary-method-8","title":"闯关 8","difficulty":"挑战","prompt":"3 台机器 2 小时做 24 个零件，1 台机器 1 小时做几个？","answer":"4","explanation":"24÷3÷2=4。"},{"id":"unitary-method-9","title":"闯关 9","difficulty":"提高","prompt":"4 瓶饮料 32 元，9 瓶饮料多少元？","answer":"72","explanation":"先求每瓶 8 元，再算 9 瓶。"},{"id":"unitary-method-10","title":"闯关 10","difficulty":"挑战","prompt":"5 台机器 3 小时做 60 个零件，1 台机器 1 小时做几个？","answer":"4","explanation":"60÷5÷3=4。"}]},{"id":"restoration-problems","title":"还原问题","practices":[{"id":"restoration-problems-1","title":"闯关 1","difficulty":"基础","prompt":"一个数加上 4 后得 10，原来是多少？","answer":"6","explanation":"10-4=6。"},{"id":"restoration-problems-2","title":"闯关 2","difficulty":"基础","prompt":"一个数减去 6 后得 9，原来是多少？","answer":"15","explanation":"9+6=15。"},{"id":"restoration-problems-3","title":"闯关 3","difficulty":"进阶","prompt":"一个数乘 4 后得 20，原来是多少？","answer":"5","explanation":"20÷4=5。"},{"id":"restoration-problems-4","title":"闯关 4","difficulty":"进阶","prompt":"一个数除以 3 后得 7，原来是多少？","answer":"21","explanation":"7×3=21。"},{"id":"restoration-problems-5","title":"闯关 5","difficulty":"提高","prompt":"一个数先加 2 再乘 3 后得 18，原来是多少？","answer":"4","explanation":"18÷3=6，6-2=4。"},{"id":"restoration-problems-6","title":"闯关 6","difficulty":"提高","prompt":"一个数先减 1 再乘 5 后得 20，原来是多少？","answer":"5","explanation":"20÷5=4，4+1=5。"},{"id":"restoration-problems-7","title":"闯关 7","difficulty":"挑战","prompt":"一个数先乘 2 再加 3 后得 17，原来是多少？","answer":"7","explanation":"17-3=14，14÷2=7。"},{"id":"restoration-problems-8","title":"闯关 8","difficulty":"挑战","prompt":"一个数先除以 2 再加 6 后得 10，原来是多少？","answer":"8","explanation":"10-6=4，4×2=8。"},{"id":"restoration-problems-9","title":"闯关 9","difficulty":"提高","prompt":"一个数先加 7 再除以 2 后得 10，原来是多少？","answer":"13","explanation":"10×2=20，20-7=13。"},{"id":"restoration-problems-10","title":"闯关 10","difficulty":"挑战","prompt":"一个数先乘 4 再减 5 后得 23，原来是多少？","answer":"7","explanation":"23+5=28，28÷4=7。"}]}]});
